import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"kiwa v1.29 released — release script filter systematic root cause SSOT 化 (release-invariants v0.1 + hook + release-smoke axis + tutorial 55 + 7 milestone snippet streak)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.29/gh-discussions-announcement.md","filePath":"announcements/v1.29/gh-discussions-announcement.md"}'),o={name:"announcements/v1.29/gh-discussions-announcement.md"};function r(n,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="kiwa-v1-29-released-—-release-script-filter-systematic-root-cause-ssot-化-release-invariants-v0-1-hook-release-smoke-axis-tutorial-55-7-milestone-snippet-streak" tabindex="-1">kiwa v1.29 released — release script filter systematic root cause SSOT 化 (release-invariants v0.1 + hook + release-smoke axis + tutorial 55 + 7 milestone snippet streak) <a class="header-anchor" href="#kiwa-v1-29-released-—-release-script-filter-systematic-root-cause-ssot-化-release-invariants-v0-1-hook-release-smoke-axis-tutorial-55-7-milestone-snippet-streak" aria-label="Permalink to &quot;kiwa v1.29 released — release script filter systematic root cause SSOT 化 (release-invariants v0.1 + hook + release-smoke axis + tutorial 55 + 7 milestone snippet streak)&quot;">​</a></h1><p>v1.29 is out. After 4 milestones (v1.14 payment / v1.25 perf-harness / v1.27 quality-metrics / v1.28 realtime) rediscovered the exact same &quot;package missing from either build filter or publish filter half&quot; bug in <code>scripts.release</code>, v1.29 stacks <strong>4 layer automation</strong> (release-smoke test axis + PostToolUse hook + SSOT docs + new npm package) to close the release-gate final hole. Every layer is a stateless check — repository under audit can adopt any subset and gain fail-fast semantics.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-test/release-invariants</code> v0.1.0</strong> (3 pure invariant checker + 1-shot aggregator, brand-new package). Pure functions — no filesystem, no network, no kiwa-specific dependency. <code>checkReleaseScriptFilter</code> (per-package both-halves check), <code>checkProvenanceFlagAbsence</code> (v1.14 removed the flag; must not creep back), <code>checkGateScriptPackageCoverage</code> (<code>test:mutation</code> must cover every publishable), <code>buildReleaseInvariantsSummary</code> (1-shot summary with <code>ok: boolean</code> + 3 sub-results). 8 behavior test PASS. kiwa runtime fixture count 34 → <strong>35</strong>.</li><li><strong>v1.29-1 release-smoke test axis</strong> (Issue #986, PR #989). <code>tests/release-smoke/tests/release-script-filter.test.ts</code> (167 lines) with dynamic package discovery + 40 per-package <code>it.each</code> assertions. Walks <code>packages/*/package.json</code>, filters by <code>@kiwa-test/*</code> scope + <code>private: false</code>, checks each publishable package appears in <strong>both</strong> halves. Fail-fast <strong>before</strong> the milestone finisher. Landed 6 previously-missing packages (agent / ai-llm / component / mcp / search / streaming) in the same PR.</li><li><strong>v1.29-2 PostToolUse hook + <code>/issue-plan</code> checklist SSOT</strong> (Issue #987). <code>hooks/post-tool-use/release-script-filter-guard.sh</code> proactive prevention. When Write / Edit tools touch <code>packages/*/package.json</code>, the hook scans the root release script for the package&#39;s filter presence and warns (does not hard-deny) if either half is missing. <code>/issue-plan</code> skill body embeds a checklist for new package additions so the invariant is called out in Issue body before implementation.</li><li><strong>v1.29-3 docs + publish</strong> (Issue #988, this PR). <code>@kiwa-test/release-invariants</code> v0.1.0 first-time npm publish + tutorial 55 (<code>release-script-filter-ssot.md</code> = systematic root cause pattern SSOT walkthrough with mock adapter + file adapter + 4 RED/GREEN behavior tests) + concept doc (<code>release-invariants.md</code> = 3 invariants catalog + systematic root cause pattern + 4-time rediscovery ledger + 7-milestone snippet validation streak) + migration guide (<code>v1.28-to-v1.29.md</code> = additive-only, breaking change 0) + snippet validation (<code>packages/release-invariants/tests/docs-tutorial-v1.29.test.ts</code> = 8 test) + VitePress publish. plugin.json 1.28.0 → 1.29.0 + new keywords + Roadmap ✅ v1.29 row + announcement 4 file + release-smoke <code>v1-29-publish.test.ts</code> (7 axis publish artefact invariant) + docs-e2e <code>V1_29_PAGES</code> (4 page render check) + <strong>release script filter check</strong> — verify <code>@kiwa-test/release-invariants</code> present in both <code>-F</code> and <code>--filter</code> halves.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>3 sub-Issues resolved</strong> (#986 / #987 / #988) — smallest sprint in kiwa milestone history</li><li><strong>3 PRs merged</strong> (v1.29-1 through v1.29-3)</li><li><strong>1 npm major addition</strong> (<code>@kiwa-test/release-invariants</code> v0.1.0) — kiwa runtime fixture 34 → <strong>35 packages</strong></li><li><strong>3 invariants</strong> + <strong>1 aggregator</strong></li><li><strong>40 per-package assertions</strong> in the fail-fast release-smoke axis</li><li><strong>8 snippet-validation tests</strong></li><li><strong>7-milestone snippet validation streak</strong> (v1.23 payment / v1.24 edge / v1.25 perf-harness / v1.26 orm / v1.27 quality-metrics / v1.28 realtime / v1.29 release-invariants)</li></ul><h2 id="why-4-layers-and-not-just-one" tabindex="-1">Why 4 layers (and not just one) <a class="header-anchor" href="#why-4-layers-and-not-just-one" aria-label="Permalink to &quot;Why 4 layers (and not just one)&quot;">​</a></h2><p>Release scripts without a shared standard fail three ways.</p><ul><li><strong>Filter symmetry drift</strong>. <code>-F</code> build filter and <code>--filter</code> publish filter are two separate halves. A contributor adds a new package to one half. Release runs green. Registry never receives the package. v1.14 / v1.25 / v1.27 / v1.28 each hit it independently.</li><li><strong>Provenance flag creep</strong>. <code>--provenance</code> came with npm CLI 10 for OIDC signing. Inside pnpm monorepos + GitHub Actions, OIDC federation is not stable. v1.14 removed it. Every subsequent milestone risks a contributor re-adding.</li><li><strong>Gate script coverage drift</strong>. <code>test:mutation</code> drives the mutation baseline. Missing a publishable package = the gate reads a partial baseline. Regression only surfaces one milestone later.</li></ul><p>The 4 rules in <code>docs/concepts/release-invariants.md</code> — 3 invariants + 1 aggregator + 1 auxiliary rule for the 7-milestone snippet streak — are the smallest set that make kiwa release scripts comparable across milestones, forks, and downstream users.</p><h2 id="_18-milestone-streak-→-19" tabindex="-1">18-milestone streak → 19 <a class="header-anchor" href="#_18-milestone-streak-→-19" aria-label="Permalink to &quot;18-milestone streak → 19&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework depth) → v1.20 (Streaming depth) → v1.21 (Auth depth) → v1.22 (Auth depth II) → v1.23 (Payment depth) → v1.24 (Edge / Serverless depth) → v1.25 (Perf-harness sweep) → v1.26 (Database depth) → v1.27 (Mutation testing sweep) → v1.28 (Realtime depth II) → <strong>v1.29 (release script filter systematic root cause SSOT)</strong>. Every milestone since v1.11 has landed its sub-Issues in full. v1.29 is the lightest sprint yet.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100 % milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth II (SurrealDB / EdgeDB / Turso / CockroachDB / TimescaleDB / QuestDB)</li><li>Perf-harness sweep II — real-machine baseline (macOS ARM64 + Linux x86_64 + Windows x86_64 3 hardware matrix)</li><li>Mutation sweep II — property-based mutation (Stryker + fast-check integration + shrink parser)</li><li>Realtime depth III — WebCodecs / WebGPU compute + AV1/VP9 hardware encoding + WHIP/WHEP ingest fidelity</li><li>Release-invariants II — provenance flag re-enablement path (OIDC federation stable + pnpm publish integration)</li></ul><p>Feedback welcome on which of these should land next.</p>',15)])])}const u=s(o,[["render",r]]);export{m as __pageData,u as default};
